package io.cascadeshield.sim;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static io.cascadeshield.sim.Models.*;
import static io.cascadeshield.sim.OpsModels.*;

class MlCorpusTest {
    @TempDir Path temporary;
    private static final ObjectMapper M=new ObjectMapper().findAndRegisterModules();
    static RoadGraph roads(){List<Node> nodes=List.of(new Node(1,80.25,13.05),new Node(2,80.251,13.05),new Node(3,80.25,13.051),new Node(4,80.251,13.051));List<Edge> edges=new ArrayList<>();
        add(edges,nodes,"AB",1,2,100);add(edges,nodes,"BD",2,4,100);add(edges,nodes,"AC",1,3,120);add(edges,nodes,"CD",3,4,120);
        return new RoadGraph(new NetworkFile("ML_UNIT_TEST_ONLY","Fixture",List.of(13d,80d,14d,81d),nodes,edges,List.of(),Map.of("demoPairs",List.of(Map.of("startNodeId",1,"destinationNodeId",4)))));}
    static void add(List<Edge> edges,List<Node> nodes,String id,long a,long b,double length){for(int i=0;i<2;i++){long from=i==0?a:b,to=i==0?b:a;edges.add(new Edge(id+i,id,from,to,a*10+b,length,36,"UNIT_TEST","residential",id,List.of(nodes.get((int)from-1).point().coordinates(),nodes.get((int)to-1).point().coordinates()),Map.of()));}}
    static Map<String,Object> parameters(){return new LinkedHashMap<>(Map.of("truckCount",2,"serviceSec",4,"departureGapSec",5,"incidentStartSec",10,"incidentDurationSec",20,"horizonSec",300,"deadlineSlackSec",5,"maxDecisions",4));}
    static State state(){return new BenchmarkScenarioGenerator(roads(),M).initial(new BenchmarkScenarioGenerator(roads(),M).generate("closure-contention",1001,parameters()));}
    @SuppressWarnings("unchecked") static List<Map<String,Object>> trucks(Map<String,Object> frame){return (List<Map<String,Object>>)frame.get("trucks");}
    @SuppressWarnings("unchecked") static Map<String,Object> features(Map<String,Object> frame){return (Map<String,Object>)trucks(frame).getFirst().get("features");}
    @Test void sharedFeatureSchemaHasStableOrderVersionHashAndExplicitMissingValues(){MlFeatureExtractor f=new MlFeatureExtractor(roads(),M);Map<String,Object> frame=f.frame(state());assertEquals(32,MlFeatureExtractor.FEATURE_NAMES.size());assertEquals(MlFeatureExtractor.FEATURE_NAMES,new ArrayList<>(features(frame).keySet()));assertEquals(64,f.featureSchemaHash().length());assertEquals(f.featureSchemaHash(),frame.get("featureSchemaHash"));assertEquals(MlFeatureExtractor.VERSION,frame.get("featureSchemaVersion"));}
    @Test void futureIncidentsAndPrivateScheduleCannotEnterFeatures(){State a=state(),b=M.convertValue(a,State.class);Incident future=new Incident();future.id="I900";future.type="CLOSURE";future.physicalId="AB";future.startSec=100;future.endSec=200;future.severity=1;future.status="SCHEDULED";b.incidents.add(future);b.replaySchedule.add(new ScheduledCommand(80,1,"DRIVER_AVAILABILITY",Map.of("id","DR1","available",true)));b.trucks.getFirst().etaSec=99999;MlFeatureExtractor f=new MlFeatureExtractor(roads(),M);assertEquals(M.valueToTree(f.frame(a)),M.valueToTree(f.frame(b)));}
    @Test void inferenceReadsDoNotMutateSourceStateOrExportTargets(){State s=state();s.operations.realizedImpacts.add(new Impact("OLD","DOCK_QUEUE",List.of("DOCK:D1_1"),List.of("T1"),0,0,0,false,"fixture","SIMULATED_OUTCOME"));var before=M.valueToTree(s);Map<String,Object> frame=new MlFeatureExtractor(roads(),M).frame(s);assertEquals(before,M.valueToTree(s));assertFalse(trucks(frame).getFirst().containsKey("labels"));assertFalse(frame.containsKey("nodeLabels"));assertTrue(M.valueToTree(frame).path("graphSnapshot").path("realizedLabels").isEmpty());}
    @Test void approvedWaitAndUnavailableDriverRemainVisibleWithoutRestorationKnowledge(){State s=state();s.trucks.getFirst().waitUntilSec=25;s.operations.drivers.getFirst().available=false;Map<String,Object> frame=new MlFeatureExtractor(roads(),M).frame(s);assertEquals(25d,features(frame).get("wait_remaining_sec"));assertEquals(0d,features(frame).get("driver_available"));assertEquals(0d,features(frame).get("rule_eta_known"));assertNull(((Map<?,?>)trucks(frame).getFirst().get("baseline")).get("remainingArrivalSec"));}
    @Test void labelsUseLaterAuthoritativeDeliveryCompletionAndStrictNewAdverseOnsets(){State initial=state();Map<String,Object> frame=new MlFeatureExtractor(roads(),M).frame(initial);State terminal=M.convertValue(initial,State.class);terminal.clockSec=100;terminal.status="COMPLETED";terminal.trucks.getFirst().arrivalSec=15;for(Delivery d:terminal.operations.deliveries){d.deliveredAtSec=d.deadlineSec+2;d.lateSec=2;d.status="DELIVERED";}terminal.operations.realizedImpacts.add(new Impact("NEW","DELIVERY_LATE",List.of("DELIVERY:L1"),List.of("T1"),20,20,2,false,"fixture","SIMULATED_OUTCOME"));new MlCorpusCli(roads(),M).attachLabels(frame,terminal);Map<?,?> labels=(Map<?,?>)trucks(frame).getFirst().get("labels");assertEquals(15d,labels.get("remainingArrivalSec"));assertEquals(1,labels.get("deliveryLate"));assertEquals(1,labels.get("futureImpact"));}
    @Test void currentAndBeyondHorizonEventsAreNotNewImpactLabels(){State s=state();Map<String,Object> frame=new MlFeatureExtractor(roads(),M).frame(s);s.clockSec=400;s.operations.realizedImpacts.add(new Impact("CURRENT","DRIVER_BUSY",List.of("DRIVER:DR1"),List.of("T1"),0,0,0,false,"fixture","SIMULATED_OUTCOME"));s.operations.realizedImpacts.add(new Impact("LATER","DOCK_QUEUE",List.of("DOCK:D1_1"),List.of("T1"),300.1,300.1,1,false,"fixture","SIMULATED_OUTCOME"));new MlCorpusCli(roads(),M).attachLabels(frame,s);assertEquals(0,((Map<?,?>)trucks(frame).getFirst().get("labels")).get("futureImpact"));}
    @Test void incompleteNegativeImpactWindowsAndUnresolvedArrivalsAreMasked(){State s=state();Map<String,Object> frame=new MlFeatureExtractor(roads(),M).frame(s);s.clockSec=50;new MlCorpusCli(roads(),M).attachLabels(frame,s);Map<?,?> labels=(Map<?,?>)trucks(frame).getFirst().get("labels");assertNull(labels.get("futureImpact"));assertNull(labels.get("remainingArrivalSec"));assertNull(labels.get("deliveryLate"));assertEquals(true,labels.get("arrivalCensored"));assertEquals(true,labels.get("impactWindowCensored"));}
    @Test void offlineCorpusExecutionIsDeterministicAndHasSeparatedLabels(){var g=new BenchmarkScenarioGenerator(roads(),M);var spec=g.generate("closure-contention",1001,parameters());var cli=new MlCorpusCli(roads(),M);Map<String,Object> a=cli.generate(spec,"train",List.of(0d,10d,30d,60d),"testgraphsha");assertEquals(M.valueToTree(a),M.valueToTree(cli.generate(spec,"train",List.of(0d,10d,30d,60d),"testgraphsha")));assertEquals("SIMULATED_RESEARCH_EXPERIMENT",a.get("provenance"));assertTrue(a.containsKey("outcomes"));assertFalse(M.valueToTree(a).path("frames").get(0).path("graphSnapshot").has("exogenousSchedule"));}
    @Test void immutableEvidenceAcceptsRepeatedSmallLongValuesButRejectsChangedContent()throws Exception{Path file=temporary.resolve("evidence.json");MlCorpusCli.immutableJson(file,Map.of("seed",1001L),M);assertDoesNotThrow(()->MlCorpusCli.immutableJson(file,Map.of("seed",1001L),M));assertThrows(IllegalStateException.class,()->MlCorpusCli.immutableJson(file,Map.of("seed",1002L),M));}
    @Test void finalUnlockRejectsDummyFrozenDeclarationsAndWrongDevelopmentChecksums()throws Exception{assertThrows(IllegalArgumentException.class,()->MlCorpusCli.validateFreeze(M.valueToTree(Map.of("frozen",true)),temporary,"p","g","s"));Map<String,Object> f=new LinkedHashMap<>(Map.of("frozen",true,"protocolSha256","p","graphSha256","g","featureSchemaHash","s","validatedModelIds",List.of("xgb-v1"),"models",Map.of("xgb-v1",Map.of("version","test")),"artifactSha256",Map.of("artifact","test"),"sourceCorpusSha256",Map.of("train","bad","validation","bad","calibration","bad")));for(String split:List.of("train","validation","calibration"))Files.writeString(temporary.resolve(split+".jsonl"),"unit fixture only\n");assertThrows(IllegalArgumentException.class,()->MlCorpusCli.validateFreeze(M.valueToTree(f),temporary,"p","g","s"));}
    @Test void finalUnlockBindsFrozenActualManifestSchemaAndDevelopmentBytes()throws Exception{
        Map<String,String> source=new LinkedHashMap<>();for(String split:List.of("train","validation","calibration")){Path file=temporary.resolve(split+".jsonl");Files.writeString(file,"UNIT_FIXTURE_ONLY "+split);source.put(split,MlExperimentProtocol.sha(Files.readAllBytes(file)));}
        Files.writeString(temporary.resolve("generation_manifest.json"),"UNIT_FIXTURE_ONLY manifest");Files.writeString(temporary.resolve("feature_schema.json"),"UNIT_FIXTURE_ONLY schema");
        Map<String,Object> f=new LinkedHashMap<>();f.put("frozen",true);f.put("protocolSha256","p");f.put("graphSha256","g");f.put("featureSchemaHash","s");f.put("validatedModelIds",List.of("xgb-v1"));f.put("models",Map.of("xgb-v1",Map.of("version","UNIT_TEST")));f.put("artifactSha256",Map.of("artifact","UNIT_TEST"));f.put("sourceCorpusSha256",source);f.put("generationManifestSha256",MlExperimentProtocol.sha(Files.readAllBytes(temporary.resolve("generation_manifest.json"))));f.put("sourceFeatureSchemaSha256",MlExperimentProtocol.sha(Files.readAllBytes(temporary.resolve("feature_schema.json"))));
        assertDoesNotThrow(()->MlCorpusCli.validateFreeze(M.valueToTree(f),temporary,"p","g","s"));Files.writeString(temporary.resolve("generation_manifest.json"),"UNIT_FIXTURE_ONLY changed declaration");assertThrows(IllegalArgumentException.class,()->MlCorpusCli.validateFreeze(M.valueToTree(f),temporary,"p","g","s"));
    }
    private Path protocolFixture()throws Exception{Map<String,Object> declaration=new LinkedHashMap<>();declaration.put("schemaVersion","cascadeshield.milestone4-protocol/1.0");declaration.put("splits",Map.of("train",List.of(1001),"validation",List.of(2001),"calibration",List.of(3001),"final",List.of(4001)));Map<String,Object> fixtureParameters=parameters();fixtureParameters.put("driverRestoreSec",120);declaration.put("families",List.of(Map.of("id","fixture-only","baseProfile","closure-contention","parameters",fixtureParameters)));declaration.put("policyBudget",Map.of("decisionIntervalSec",30,"rolloutHorizonSec",300,"maxDecisions",4));declaration.put("splitIsolation",Map.of("enabled",true,"fleetSizeGroups",Map.of("train",Map.of("2",2),"validation",Map.of("2",3),"calibration",Map.of("2",4),"final",Map.of("2",5))));Path file=temporary.resolve("protocol-fixture.json");Files.write(file,M.writeValueAsBytes(declaration));return file;}
    @Test void fleetGroupPartitionChangesActualTrucksDriversDeliveriesAndAssignments()throws Exception{MlExperimentProtocol protocol=new MlExperimentProtocol(protocolFixture(),roads(),M);int expected=2;for(String split:List.of("train","validation","calibration","final")){var s=protocol.scenarios(split).getFirst();assertEquals(expected,((Number)s.parameters().get("truckCount")).intValue());assertEquals(expected,((List<?>)s.configuration().get("trucks")).size());Map<?,?> ops=M.convertValue(s.configuration().get("operations"),Map.class);for(String key:List.of("drivers","deliveries","assignments"))assertEquals(expected,((List<?>)ops.get(key)).size());expected++;}assertEquals(4,((List<?>)protocol.manifest("g","p").get("cases")).size());}
    @Test void continuousGuardCatchesAcrossBinNeighborsAndIgnoresUnusedIncidentNonce()throws Exception{MlExperimentProtocol protocol=new MlExperimentProtocol(protocolFixture(),roads(),M);var generator=new BenchmarkScenarioGenerator(roads(),M);Map<String,Object>a=parameters(),b=parameters();a.put("horizonSec",600);b.put("horizonSec",600);a.put("serviceSec",59.9);b.put("serviceSec",60.1);a.put("closureCount",0);b.put("closureCount",0);a.put("rainSlowdownCount",0);b.put("rainSlowdownCount",0);a.put("incidentStartSec",10);b.put("incidentStartSec",200);a.put("contention",0);b.put("contention",0);var first=generator.generate("closure-contention",1001,a);var second=generator.generate("closure-contention",1001,b);assertTrue(protocol.continuouslyNear(first,second));b.put("serviceSec",140);assertFalse(protocol.continuouslyNear(first,generator.generate("closure-contention",1001,b)));}
}
